import {OnlineMatch} from './online.js?v=online-15';
import {levels,loadProgress,completeLevel,saveProgress} from './progression.js?v=online-15';
import {analytics} from './analytics.js';
import {getAllAvailableLines,getScores,isGameOver,getWinner} from './gameLogic.js?v=online-15';
import {Match} from './match.js?v=online-15';
const $=id=>document.getElementById(id), NS='http://www.w3.org/2000/svg';
let board,turn=0,config,gameAnalytics,progress=loadProgress(localStorage),levelRecorded=false;
function levelOptions(){const select=$('difficulty'),value=select.value;select.replaceChildren();levels.forEach((level,i)=>{const option=document.createElement('option');option.value='level-'+i;option.textContent=`Level ${i+1} - ${level.name}${i<progress.completed?' - Complete':i>progress.completed?' - Locked':''}`;option.disabled=i>progress.completed;select.append(option);});for(const d of ['easy','medium','hard']){const option=document.createElement('option');option.value=d;option.textContent=`Practice - ${d}`;select.append(option);}select.value=value||'level-'+Math.min(progress.completed,levels.length-1);}
levelOptions();$('difficulty').value='level-'+Math.min(progress.completed,levels.length-1);
const changed=state=>{board=state.board;turn=state.turn;config=state.config;render();gameAnalytics?.observe({hasMoves:state.moves.length>0,finished:isGameOver(state.board),mode:state.config.mode==='online'?'local':state.config.mode});};
const localMatch=new Match({onChange:changed});let match=localMatch;
const online=new OnlineMatch({onChange:changed,onMessage:text=>{$('room-message').textContent=text;}});
const colors=['#b9ef81','#f5b398'];
function svg(tag,attrs,parent=$('board')){const e=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
function start(){if($('mode').value==='online')return;online.cancel();match=localMatch;levelRecorded=false;const selected=$('difficulty').value,index=selected.startsWith('level-')?Number(selected.slice(6)):null,level=index===null?null:levels[index];gameAnalytics=analytics.newGame();match.start({size:'diamond',mode:$('mode').value,difficulty:level?.difficulty||selected,mistakes:level?.mistakes||0,level:index,first:$('first').value==='random'?'random':Number($('first').value),names:[$('p1').value.trim()||'Player 1',$('mode').value==='ai'?'Computer':$('p2').value.trim()||'Player 2']});}
function play(pos){match.play(pos);}
function render(){const root=$('board');root.replaceChildren();const n=board.rows,step=400/n,off=50;const scores=getScores(board),total=board.shapeMask?25:n*n,done=isGameOver(board);$('starter').textContent=`${config.names[match.starter]} starts${config.first==='random'?' · randomly chosen':''}`;$('board-label').textContent=config.size==='diamond'?'DIAMOND BOARD':`${n} × ${n} BOARD`;
for(let i=0;i<2;i++){$('name'+i).textContent=config.names[i];$('score'+i).textContent=scores[i];$('player'+i).classList.toggle('active',turn===i&&!done);$('player'+i).querySelector('.turn-marker').textContent=i===1&&config.mode==='ai'?'THINKING…':'YOUR TURN';}
for(let r=0;r<n;r++)for(let c=0;c<n;c++){const owner=board.boxes[r][c];if(owner!==null){svg('rect',{x:off+c*step+6,y:off+r*step+6,width:step-12,height:step-12,rx:8,fill:colors[owner],opacity:'.16'});const text=svg('text',{x:off+(c+.5)*step,y:off+(r+.5)*step+5,'text-anchor':'middle',fill:colors[owner],'font-size':15,'font-family':'sans-serif'});text.textContent=owner===0?'01':'02';}}
const available=new Set(getAllAvailableLines(board).map(p=>`${p.type}-${p.row}-${p.col}`)),dots=new Set();
for(const type of ['h','v'])for(let r=0;r<(type==='h'?n+1:n);r++)for(let c=0;c<(type==='h'?n:n+1);c++){const adj=type==='h'?[[r-1,c],[r,c]]:[[r,c-1],[r,c]];if(!adj.some(([a,b])=>a>=0&&b>=0&&a<n&&b<n&&(!board.shapeMask||board.shapeMask[a][b])))continue;const x1=off+c*step,y1=off+r*step,x2=x1+(type==='h'?step:0),y2=y1+(type==='v'?step:0),attrs={x1,y1,x2,y2};dots.add(`${x1},${y1}`);dots.add(`${x2},${y2}`);const drawn=type==='h'?board.hLines[r][c]:board.vLines[r][c],owner=type==='h'?board.hLineOwner[r][c]:board.vLineOwner[r][c];if(drawn)svg('line',{...attrs,class:owner===null?'fixed':'played',stroke:owner===null?'#657a67':colors[owner]});else if(available.has(`${type}-${r}-${c}`)){const enabled=!done&&(config.mode!=='online'||(online.state?.ready&&turn===online.state.seat&&!online.busy))&&!(config.mode==='ai'&&turn===1),g=svg('g',{class:'edge',role:'button',tabindex:enabled?'0':'-1','aria-label':`${type==='h'?'Horizontal':'Vertical'} line, row ${r+1}, column ${c+1}`,'aria-disabled':String(!enabled)});svg('line',{...attrs,class:'rail'},g);svg('line',{...attrs,class:'hit'},g);g.addEventListener('click',()=>play({type,row:r,col:c}));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();play({type,row:r,col:c});}});}}
for(const dot of dots){const [cx,cy]=dot.split(',');svg('circle',{cx,cy,r:4.7,fill:'#dbe5d8','pointer-events':'none'});}
const count=scores[0]+scores[1];$('claimed').textContent=`${count} of ${total} boxes claimed`;$('progress').style.width=`${count/total*100}%`;$('undo').hidden=config.mode==='online';$('undo').disabled=config.mode==='ai'?!match.history.some(h=>h.turn===0):!match.history.length;
const last=match.moves.at(-1),computerMoves=match.moves.filter(m=>m.player===1),lastComputer=computerMoves.at(-1);
$('computer-activity').hidden=config.mode!=='ai';
$('computer-activity').textContent=lastComputer?`Computer played ${computerMoves.length} ${computerMoves.length===1?'line':'lines'}. Latest: ${lastComputer.type==='h'?'horizontal':'vertical'}, row ${lastComputer.row+1}, column ${lastComputer.col+1}${lastComputer.captured?` · captured ${lastComputer.captured} ${lastComputer.captured===1?'box':'boxes'}`:''}.`:'Computer will draw peach lines automatically on its turn.';
for(const line of root.querySelectorAll('.played')){if(line.getAttribute('stroke')===colors[1])line.classList.add('computer-line');}
if(last){const x=50+last.col*step,y=50+last.row*step;svg('circle',{cx:x+(last.type==='h'?step/2:0),cy:y+(last.type==='v'?step/2:0),r:5,fill:colors[last.player],class:'latest-move','pointer-events':'none'});}
$('level-progress').hidden=config.mode!=='ai';$('level-progress').textContent=`Journey: ${progress.completed} / ${levels.length} levels completed${config.level===null?' - Practice match':` - Level ${config.level+1}`}`;$('next-level').hidden=true;
if(config.mode==='online'){$('new').disabled=!done||online.busy;$('new').textContent=done?'Request rematch':'Game in progress';$('room-code').value=online.state.id;$('room-link').value=location.origin+'/#room='+online.state.id;$('room-share').hidden=false;$('create-room').disabled=true;$('join-room').disabled=true;$('room-code').readOnly=true;}
if(done){const winner=getWinner(board);if(!levelRecorded&&config.mode==='ai'&&config.level!==null){progress=completeLevel(progress,config.level,winner);saveProgress(localStorage,progress);levelRecorded=true;levelOptions();}$('next-level').hidden=!(config.mode==='ai'&&config.level!==null&&winner===0&&config.level<levels.length-1);$('status').textContent=winner==='tie'?`A perfect tie! ${scores[0]} – ${scores[1]}. Start fresh for a rematch.`:`${config.names[winner]} wins ${scores[winner]} – ${scores[1-winner]}! Ready for a rematch?`;}
else $('status').textContent=match.isComputerTurn()?'Computer is choosing a line…':last?.captured?`${config.names[last.player]} captured ${last.captured===1?'a box':last.captured+' boxes'} — ${config.names[turn]==='You'?'your':config.names[turn]+"'s"} turn.`:`${config.names[turn]==='You'?'Your':config.names[turn]+"'s"} move. Pick a line between two dots.`;
if(config.mode==='online'){$('status').textContent=!online.state.ready?'Room ready. Share the link and wait for your friend.':done?($('status').textContent+(online.state.rematch.includes(online.state.seat)?' Waiting for your friend to accept the rematch.':online.state.rematch.length?' Your friend wants a rematch.':'')):online.busy?'Sending your move…':turn===online.state.seat?'Your turn. Pick a line.':`${config.names[turn]}'s turn. Waiting for their move…`;}
}

function changeMode(){const mode=$('mode').value,ai=mode==='ai',isOnline=mode==='online';online.cancel();match=localMatch;$('online-panel').hidden=!isOnline;$('room-share').hidden=true;$('create-room').disabled=false;$('join-room').disabled=false;$('room-code').readOnly=false;$('room-message').textContent='';$('difficulty').disabled=!ai;$('first').disabled=isOnline;$('p2').disabled=ai||isOnline;$('p2').value=ai?'Computer':'Player 2';$('first').querySelector('[value="1"]').textContent=ai?'Computer starts':'Player 2 starts';$('new').disabled=isOnline;$('new').textContent=isOnline?'Create or join a room':'Start fresh ↗';localMatch.start({mode:isOnline?'local':mode,size:'diamond',names:[$('p1').value||'You',ai?'Computer':'Player 2'],first:0,level:null});if(isOnline){$('status').textContent='Create a room or join your friend using their room code.';$('board').replaceChildren();$('undo').hidden=true;}else start();}
$('mode').addEventListener('change',changeMode);$('new').onclick=()=>{if(config.mode==='online')online.rematch();else start();};$('difficulty').addEventListener('change',start);
async function connectRoom(action){
 const room=$('room-code').value.trim().toLowerCase();$('room-message').textContent='Connecting…';$('create-room').disabled=true;$('join-room').disabled=true;localMatch.cancel();match=online;
 try{await online.connect(action,{room,name:$('p1').value.trim()||'Player'});if(online.state){history.replaceState(null,'','#room='+online.state.id);gameAnalytics=analytics.newGame();}}
 catch{match=localMatch;}
 finally{$('create-room').disabled=!!online.state;$('join-room').disabled=!!online.state;}
}
$('create-room').onclick=()=>connectRoom('create');$('join-room').onclick=()=>connectRoom('join');
$('copy-room').onclick=async()=>{try{await navigator.clipboard.writeText($('room-link').value);$('room-message').textContent='Invite link copied. Send it to your friend.';}catch{$('room-link').select();$('room-message').textContent='Select and copy the invite link.';}};
$('leave-room').onclick=()=>{history.replaceState(null,'',location.pathname);$('mode').value='ai';changeMode();};
$('next-level').onclick=()=>{$('difficulty').value='level-'+(config.level+1);start();};
$('undo').onclick=()=>match.undo();
$('first').addEventListener('change',start);
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();start();

const invite=/^#room=([a-f0-9]{16})$/.exec(location.hash);if(invite){$('mode').value='online';changeMode();$('room-code').value=invite[1];if(online.credential(invite[1]))connectRoom('join');}
analytics.visit();
